<style>
.developer-workspace{color:var(--theme-header-text-color);max-width:1400px;margin:auto}.developer-heading{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:3px 0 25px}.developer-heading h1{font-size:28px;font-weight:650;letter-spacing:-.035em}.developer-heading p,.developer-section-heading p{font-size:13px;color:var(--theme-muted-text-color);margin-top:7px;line-height:1.6}.developer-base{display:flex;gap:10px;align-items:center;max-width:55%;font-size:11px}.developer-base>span{white-space:nowrap;color:var(--theme-muted-text-color)}.developer-base code{overflow-wrap:anywhere;font-size:11px}.developer-tabs{display:flex;gap:22px;border-bottom:1px solid var(--theme-border-color);margin-bottom:26px}.developer-tabs>button{display:flex;align-items:center;gap:8px;padding:12px 2px;font-size:13px;font-weight:600;color:var(--theme-muted-text-color);border-bottom:2px solid transparent;margin-bottom:-1px;white-space:nowrap}.developer-tabs>button[aria-selected=true]{color:var(--theme-accent);border-color:var(--theme-accent)}.developer-tabs>button>span{font-size:10px;border-radius:6px;padding:2px 6px;background:var(--theme-surface-subtle)}
.developer-section-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:20px}.developer-section-heading h2{font-size:19px;font-weight:600;letter-spacing:-.02em}.developer-form,.developer-doc-card{border:1px solid var(--theme-card-border-color);border-radius:12px;padding:22px;background:var(--theme-surface-base)}.developer-form{margin:0 0 20px;display:grid;gap:22px}.developer-form legend{font-size:12px;font-weight:600;margin-bottom:12px}.developer-form-actions{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid var(--theme-divider-border-color);padding-top:16px}.developer-permissions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.developer-two-fields{display:grid;grid-template-columns:1fr 1.8fr;gap:16px}.developer-error{font-size:12px;color:#ba4638!important;margin-top:8px;overflow-wrap:anywhere}.developer-notice{display:flex;align-items:center;gap:10px;border:1px solid var(--theme-border-color);background:var(--theme-surface-soft);border-radius:9px;padding:12px 15px;margin-bottom:18px;font-size:12px;color:var(--theme-muted-text-color)}
.developer-list{border:1px solid var(--theme-card-border-color);border-radius:12px;background:var(--theme-surface-base);overflow:hidden}.developer-row{display:flex;align-items:flex-start;gap:16px;padding:20px;border-bottom:1px solid var(--theme-divider-border-color)}.developer-row:last-child{border:0}.developer-row-icon{width:36px;height:36px;display:grid;place-items:center;background:var(--theme-surface-subtle);color:var(--theme-accent);border-radius:9px;flex-shrink:0}.developer-row-body{flex:1;min-width:0}.developer-row-body h3{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:14px;font-weight:600}.developer-row-body p{font-size:12px;color:var(--theme-muted-text-color);margin-top:7px}.developer-row-body code{display:block;font-size:11px;color:var(--theme-muted-text-color);margin-top:8px;overflow-wrap:anywhere}.developer-url{overflow-wrap:anywhere}.developer-tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.developer-tags span{font-size:10px;background:var(--theme-surface-soft);border:1px solid var(--theme-border-color);border-radius:5px;padding:3px 7px}.developer-row-actions{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:7px;max-width:430px}.developer-empty{padding:50px 20px;text-align:center}.developer-empty>i{display:inline-grid;place-items:center;width:50px;height:50px;border-radius:12px;font-size:21px;background:var(--theme-surface-subtle);color:var(--theme-accent)}.developer-empty h3{font-size:17px;font-weight:600;margin:17px 0 7px}.developer-empty p{font-size:13px;color:var(--theme-muted-text-color)}.developer-empty button{margin-top:18px;color:var(--theme-accent);font-size:12px;font-weight:600}
.developer-filters{display:flex;align-items:flex-end;gap:12px;margin-bottom:18px}.developer-filters>div{min-width:170px}.developer-filters>span{margin-left:auto;font-size:12px;color:var(--theme-muted-text-color);padding-bottom:10px}.developer-more{text-align:center;margin:18px}.developer-doc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.developer-doc-wide{grid-column:1/-1}.developer-doc-card{min-width:0}.developer-doc-card h3{font-weight:600;font-size:15px}.developer-doc-card p{font-size:12px;line-height:1.8;color:var(--theme-muted-text-color);margin-top:12px}.developer-doc-title{display:flex;align-items:center;justify-content:space-between;gap:14px}.developer-code{background:var(--theme-surface-soft);border:1px solid var(--theme-border-color);border-radius:8px;padding:14px;font-size:12px;line-height:1.8;overflow:auto;margin:14px 0;max-height:420px}.developer-secret{white-space:pre-wrap;overflow-wrap:anywhere;padding:16px;border:1px solid var(--theme-border-color);border-radius:8px;background:var(--theme-surface-soft);font-size:13px}.developer-detail-summary{font-size:12px;overflow-wrap:anywhere;margin-bottom:16px}.developer-workspace label:has(input:focus-visible){outline:2px solid var(--theme-accent);outline-offset:5px;border-radius:4px}
@media(max-width:1000px){.developer-heading{align-items:flex-start;flex-direction:column;gap:15px}.developer-base{max-width:100%}.developer-row{flex-wrap:wrap}.developer-row-actions{max-width:100%;flex-basis:100%}.developer-permissions{grid-template-columns:1fr;gap:16px}}
@media(max-width:639px){.developer-heading h1{font-size:25px}.developer-tabs{gap:18px;overflow-x:auto;margin-bottom:20px}.developer-tabs>button{font-size:12px}.developer-section-heading{align-items:flex-start;gap:12px}.developer-section-heading h2{font-size:18px}.developer-section-heading>button{white-space:nowrap}.developer-form,.developer-doc-card{padding:16px}.developer-two-fields,.developer-doc-grid{grid-template-columns:1fr}.developer-filters{flex-wrap:wrap}.developer-filters>div{flex:1;min-width:130px}.developer-filters>span{width:100%;margin:0;padding:0}.developer-row{padding:16px;gap:12px}.developer-empty{padding:35px 16px}.developer-base>span{display:none}.developer-code{font-size:11px}.developer-doc-wide{grid-column:auto}}
